    const auto f_19 = 1.0 / alpha;
    const auto f_20 = beta / (alpha * p);
    const auto f_21 = 1.5 / alpha;
    const auto f_22 = 1.5 * beta / (alpha * p);

    auto *t_0 = buffer.data(target + 0);
    auto *t_1 = buffer.data(target + 1);
